import configparser
import os

def status():
    cfg = configparser.ConfigParser()
    cfg.read('settings.ini')
    if cfg.getboolean('service', 'needs_reconnect', fallback=True):
        return 'reconnect'
    if not cfg.get('service', 'endpoint', fallback=''):
        return 'no endpoint'
    if not os.path.exists('local_plugin.py'):
        return 'plugin missing'
    return 'connected'

if __name__ == '__main__':
    print(status())

