import json

def load_gates():
    with open('gates.json') as f:
        data = json.load(f)
    return data.get('user', [])

def run_gates(row, gates):
    if 'positive_amount' in gates and row.get('amount', 0) < 0:
        return False, 'amount must be positive'
    return True, 'ok'

def import_row(row):
    gates = load_gates()
    ok, msg = run_gates(row, gates)
    if not ok:
        return {'status': 'rejected', 'reason': msg}
    return {'status': 'imported', 'row': row}

