class Prompt:
    def __init__(self):
        self.dismissed = False
        self.window_offset = (0, 0)
        self.buttons = {
            'save': {'x': 10, 'y': 20},
            'not_now': {'x': 100, 'y': 20},
        }
        self.accessibility = [{'label': 'Not Now', 'action': 'dismiss'}]

    def set_offset(self, dx, dy):
        self.window_offset = (dx, dy)

    def click(self, x, y):
        for name, button in self.buttons.items():
            ax = button['x'] + self.window_offset[0]
            ay = button['y'] + self.window_offset[1]
            if (x, y) == (ax, ay):
                if name == 'not_now':
                    self.dismissed = True
                return True
        return False

    def perform_action(self, label):
        if label == 'Not Now':
            self.dismissed = True
            return True
        return False

