import os, json

def summarize(tasks_dir):
    result = {"done": 0, "running": 0, "blocked": 0, "tasks": []}
    for name in os.listdir(tasks_dir):
        if not name.endswith(".json"):
            continue
        path = os.path.join(tasks_dir, name)
        with open(path) as f:
            data = json.load(f)
        if data.get("status") == "running":
            result["running"] += 1
            result["tasks"].append(data.get("name"))
    return result

