class App:
    def __init__(self):
        self.screen = 'home'
        self.selected = None

    def tap(self, label):
        if self.screen == 'home' and label == 'list':
            self.screen = 'list'
        elif self.screen == 'list' and label.startswith('item'):
            self.selected = 1
            self.screen = 'detail'
        elif self.screen == 'detail' and label == 'back':
            self.screen = 'list'

    def visible_text(self):
        if self.screen == 'home':
            return 'Home'
        if self.screen == 'list':
            return 'Items: 1, 2, 3'
        if self.screen == 'detail':
            if self.selected is None:
                return 'No item selected'
            return f'Details for {self.selected}'
        return ''

