import json
import os

STATE = "state.json"

def load_state():
    if os.path.exists(STATE):
        return json.load(open(STATE))
    return {"threads": {}}

def usage(thread_id, events):
    state = load_state()
    pinned = state["threads"].get(thread_id, {}).get("pinned", 0)
    real = sum(event["tokens"] for event in events)
    return max(pinned, real)

def can_work(thread_id, events, limit):
    return usage(thread_id, events) < limit

