import threading


class Pool:
    def __init__(self):
        self.workers = []
        self.results = []

    def submit(self, value):
        worker = threading.Thread(target=self._run, args=(value,))
        worker.start()
        self.workers.append(worker)

    def _run(self, value):
        self.results.append(value * 2)

    def running(self):
        return [w for w in self.workers if w.is_alive()]

