    cfg = {}
    for line in open("budget.cfg"):
        if "=" in line:
            key, value = line.strip().split("=")
            cfg[key.strip()] = value.strip()
    return cfg


def load_tasks():
    with open("tasks.csv") as handle:
        return list(csv.DictReader(handle))


def load_ledger():
    if not os.path.exists("ledger.txt"):
        return 0
    return int(open("ledger.txt").read().strip() or 0)


def main(prompt=input):
    limit = int(load_budget()["limit"])
    spent = load_ledger()
    done = []
    for task in load_tasks():
        cost = int(task["cost"])
        if spent + cost > limit:
            print("no budget left, stopping")
            break
        if done and prompt("authorize the next job? ") != "yes":
            break
        spent += cost
        done.append(task["id"])
        print("ran", task["id"])
    open("ledger.txt", "w").write(str(spent))
    open("done.txt", "w").write("\n".join(done))
    return done


if __name__ == "__main__":
    main()

