from worker import do_work

def connect():
    cfg = configparser.ConfigParser()
    cfg.read('config.ini')
    timeout = cfg.getint('connection', 'timeout')
    result = {}
    def target():
        result['value'] = do_work()
    t = threading.Thread(target=target)
    t.start()
    t.join(timeout)
    if t.is_alive():
        raise TimeoutError('cancelled before finishing')
    return result['value']

def is_installed():
    cfg = configparser.ConfigParser()
    cfg.read('state.ini')
    return not cfg.getboolean('install', 'locked')

