files.evaluator.py:
def evaluate(expr):
    parts = expr.split()
    total = int(parts[0])
    i = 1
    while i < len(parts):
        op = parts[i]
        num = int(parts[i+1])
        if op == '+':
            total += num
        elif op == '-':
            total -= num
        elif op == '*':
            total *= num
        elif op == '/':
            total //= num
        i += 2
    return total

