import json
import os
import time

def start_services(config_path='services.json'):
    cfg = json.load(open(config_path))
    if os.path.exists('startup.lock'):
        raise RuntimeError('startup already in progress')
    results = {}
    timeout = cfg.get('timeout', 1)
    for svc in cfg.get('services', []):
        if svc.get('name') == 'cache':
            time.sleep(0.3)
        if timeout < 0.1:
            results[svc['name']] = 'timeout'
        else:
            results[svc['name']] = 'ready'
    return results

