class Item:
    def __init__(self, name, qty, price):
        self.name = name
        self.qty = qty
        self.price = price
    def value(self):
        return self.qty * self.price

def total_value(items):
    total = 0
    for item in items:
        if isinstance(item, Item):
            total += item.value()
        else:
            total += item['qty'] * item['price']
    return total

def most_valuable(items):
    best = None
    best_value = -1
    for item in items:
        value = item['qty'] * item['price']
        if value > best_value:
            best_value = value
            best = item
    return best

def total_quantity(items):
    total = 0
    for item in items:
        if isinstance(item, Item):
            total += item.qty
        else:
            total += item['qty']
    return total

