import json

STATE = {'next_index': 0, 'done': []}


def load_records(path='records.csv'):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))


def process_one(record):
    return record['name'].upper()


def save_state(path='progress.json'):
    with open(path, 'w') as f:
        json.dump(STATE, f)


def work_until_stopped(stop_after=None):
    records = load_records()
    for i, record in enumerate(records):
        if stop_after is not None and i >= stop_after:
            # TODO: save partial work before returning
            return
        STATE['done'].append(process_one(record))
        STATE['next_index'] = i + 1
    save_state()


if __name__ == '__main__':
    work_until_stopped()

