files.summarize.py:
"""Summarizes a log file into a few counts."""


def read_lines(path):
    with open(path) as handle:
        return [line.strip() for line in handle if line.strip()]


def classify(line):
    if line.startswith("ERROR"):
        return "error"
    if line.startswith("WARN"):
        return "warn"
    return "info"


def counts(lines):
    result = {"error": 0, "info": 0}
    for line in lines:
        kind = classify(line)
        if kind in result:
            result[kind] += 1
    return result


def report(lines):
    data = counts(lines)
    return [
        "errors: %d" % data["error"],
        "warnings: %d" % data.get("warn", 0),
        "info: %d" % data["info"],
    ]


def run(path):
    return report(read_lines(path))


if __name__ == "__main__":
    for entry in run("app.log"):
        print(entry)

