class TestRetries(unittest.TestCase):
    def test_retries_until_pass(self):
        calls = {'n': 0}
        def flaky():
            calls['n'] += 1
            if calls['n'] < 3:
                raise RuntimeError('flaky')
        result = run_with_retries(flaky, max_attempts=3)
        self.assertTrue(result.passed)
        self.assertEqual(result.attempts, 3)

